import com.onebytelabs.zlplay.audio.*;
import com.onebytelabs.zlplay.project.*;
import java.util.*;
public final class PlaybackRulesTest {
 private static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);}
 private static PcmTrack tone(String name,float value){float[] data=new float[144000];Arrays.fill(data,value);return new PcmTrack(name,48000,1,data);}
 public static void main(String[] args){DemoMixer m=new DemoMixer();m.load(new PcmTrack[]{tone("VS",.25f),tone("Guide",.2f),tone("Click",.1f)});ProjectSpec p=new ProjectSpec();p.duration=3;for(String n:new String[]{"VS","Guide","Click"}){ProjectSpec.Track t=new ProjectSpec.Track();t.name=n;p.tracks.add(t);}for(int i=0;i<3;i++)p.regions.add(new ProjectSpec.Region("Part "+i,i,i+1,""));m.configureProject(p);for(int i=0;i<3;i++)m.setGain(i,1);float[] block=new float[96000];m.seek(1.8);m.play();m.setLoop(true);m.render(block,48000);check(m.position()>=1&&m.position()<2,"Loop repeats the current region, not the song");check(Math.abs(block[block.length-2]-.35)<.002,"Region loop mutes guide only");m.setClick(true);m.render(block,48000);m.render(block,48000);check(Math.abs(block[block.length-2]-.1)<.002,"Solo Click fades VS and guide while preserving project click");check(m.isLoop()&&m.position()>=1&&m.position()<2,"Solo Click holds its current region");m.setClick(false);check(!m.isLoop(),"Leaving Solo Click releases region loop");m.seek(.2);m.play();m.setLoop(true);m.selectRegion(2);m.render(block,48000);check(m.position()>=2&&m.position()<2.3&&!m.isLoop(),"Queued jump takes precedence over loop");m.seek(0);m.setVsLevel(0);m.setGuideLevel(0);m.setClickLevel(0);m.play();m.render(block,48000);check(Math.abs(block[block.length-2])<.00001,"Special channels and VS gains route independently");m.setMasterLevel(0);m.setVsLevel(1);m.render(block,100);check(block[0]==0,"Master controls the final mix");m.stop();m.setMasterLevel(1);m.setClickLevel(1);m.setClick(true);m.render(block,4800);check(m.position()==0&&!m.isPlaying(),"Standalone click does not start the project");m.setPad(true);m.prepareProjectChange(true);check(m.isPad()&&!m.isPlaying()&&!m.isClick(),"Song change preserves only pad when enabled");m.prepareProjectChange(false);check(!m.isPad(),"Song change stops pad when disabled");float accented=NativeClickSound.sample(100,24000,4,0,true),normal=NativeClickSound.sample(100,24000,4,0,false);check(Math.abs(accented-normal)>.001,"Native accent toggle changes first beat PCM");System.out.println("PASS: region loop, solo-click routing/fade, guide mute, queued jump precedence, VS/special/master gains and standalone click");}
}
